using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

namespace BubbleWash.EditorTools
{
    /// <summary>
    /// On the first open of the project, builds the menu and Level 1 scenes automatically once the
    /// Meshy GLBs have been imported by glTFast, and opens the menu. A Level 1 scene generated by an
    /// older version of the builder (see <see cref="Level1SceneBuilder.SceneVersion"/>) is rebuilt.
    /// Otherwise later opens leave the scenes alone; rebuild any time from Bubble Wash > 1.
    /// </summary>
    [InitializeOnLoad]
    static class FirstOpenSetup
    {
        const string SessionKey = "BubbleWash.FirstOpenChecked";
        static int _waitFrames;

        static FirstOpenSetup()
        {
            if (Application.isBatchMode || SessionState.GetBool(SessionKey, false)) return;
            EditorApplication.update += Poll;
        }

        static void Poll()
        {
            if (EditorApplication.isCompiling || EditorApplication.isUpdating || EditorApplication.isPlayingOrWillChangePlaymode) return;
            if (++_waitFrames < 30) return;
            EditorApplication.update -= Poll;
            SessionState.SetBool(SessionKey, true);

            bool levelOutdated = Level1SceneBuilder.SceneIsOutdated();
            if (!levelOutdated && File.Exists(MainMenuBuilder.ScenePath))
            {
                if (string.IsNullOrEmpty(EditorSceneManager.GetActiveScene().path))
                    EditorSceneManager.OpenScene(MainMenuBuilder.ScenePath);
                return;
            }
            if (AssetDatabase.LoadAssetAtPath<GameObject>(Level1SceneBuilder.CastlePath) == null)
            {
                Debug.LogWarning("[BubbleWash] The castle GLB is not imported yet. Make sure the glTFast package finished installing, then use Bubble Wash > 1. Build Level 1 Scene.");
                return;
            }
            Debug.Log(File.Exists(Level1SceneBuilder.ScenePath)
                ? "[BubbleWash] The generated Level 1 scene is from an older version: rebuilding it with Screens 5-12..."
                : "[BubbleWash] First open: building the menu (Screens 1-2) and Level 1 (Screens 3-12) from the Meshy models...");
            if (levelOutdated) Level1SceneBuilder.Build();
            if (!File.Exists(MainMenuBuilder.ScenePath)) MainMenuBuilder.Build();
            EditorSceneManager.OpenScene(MainMenuBuilder.ScenePath);
        }
    }
}
